    assertThat(JavaWriter.stringLiteral("\f")).isEqualTo("\"\\f\"");
    assertThat(JavaWriter.stringLiteral("\r")).isEqualTo("\"\\r\"");

    // Control characters
    for (char i = 0x1; i <= 0x1f; i++) {
