    public Flux<ServiceBroker> list() {
        return this.cloudFoundryClient
            .flatMapMany(DefaultServiceAdmin::requestListServiceBrokers)
            .map(this::toServiceBroker)
            .transform(OperationsLogging.log("List Service Brokers"))
            .checkpoint();
